// NCC mới xuất hiện trong 30 ngày gần đây, và NCC cũ đã lâu (> 60 ngày) không có giao dịch
// nào mới. NCC mới cần xác minh/đàm phán giá; NCC ngừng giao dịch có thể là dấu hiệu họ đóng
// cửa hoặc gara đã âm thầm chuyển nguồn hàng mà không ai ghi nhận chính thức. Chỉ gửi khi có
// ít nhất 1 trong 2 nhóm phát sinh — không làm phiền hộp thư nếu không có gì đáng chú ý.
const d = $json;
const news = d.new_suppliers || [];
const stales = d.stale_suppliers || [];
if (news.length === 0 && stales.length === 0) return { json: { email_to: '' } };

const vnd = n => new Intl.NumberFormat('vi-VN').format(n || 0) + '₫';
const fmt = s => new Date(s).toLocaleDateString('vi-VN');

const newRows = news.map(s => `<tr><td>${s.partner_name}</td><td>${fmt(s.first_seen)}</td><td align="right">${vnd(s.total_spent)}</td></tr>`).join('');
const staleRows = stales.map(s => `<tr><td>${s.partner_name}</td><td>${fmt(s.last_seen)}</td><td align="right">${vnd(s.total_spent)}</td></tr>`).join('');

let html = `<h2>🔄 Biến động nhà cung cấp tháng này</h2>`;
if (news.length) {
  html += `<h3>🆕 ${news.length} NCC mới</h3>`
    + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
    + `<tr><th>Nhà cung cấp</th><th>Giao dịch đầu</th><th>Đã chi</th></tr>${newRows}</table>`;
}
if (stales.length) {
  html += `<h3 style="margin-top:20px">💤 ${stales.length} NCC lâu không giao dịch (>${d.stale_days} ngày)</h3>`
    + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
    + `<tr><th>Nhà cung cấp</th><th>Giao dịch gần nhất</th><th>Tổng đã chi</th></tr>${staleRows}</table>`;
}
html += `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `🔄 ${news.length} NCC mới, ${stales.length} NCC lâu không giao dịch`,
  email_html: html
} };
